/**
 * qcm-examen-banque-3.js
 * ---------------------------------------------------------------------
 * Complément de la banque du « QCM examen » : compétences 6 à 10.
 * Même format que qcm-examen-banque.js (lire l'en-tête de ce fichier).
 * ---------------------------------------------------------------------
 */
window.TSSR_QCM_BANQUE = (window.TSSR_QCM_BANQUE || []).concat([
  /* ================= Compétence 6 : Infrastructure virtualisée ================= */
  { c: 6, q: "Qu'est-ce que VMware ESXi ?",
    o: ["Un hyperviseur de type 1 installé directement sur le serveur physique", "Un logiciel de virtualisation pour poste de travail", "Un système de sauvegarde", "Un antivirus"], a: 0,
    e: "ESXi est l'hyperviseur de VMware : il s'installe à la place d'un système d'exploitation, directement sur le matériel (type 1, ou « bare metal »). Il fait tourner les VM et s'administre via son interface web ou via vCenter. VMware Workstation, lui, est de type 2 (installé sur Windows ou Linux)." },
  { c: 6, q: "Qu'est-ce qu'un datastore dans vSphere ?",
    o: ["Un espace de stockage (local, SAN ou NAS) où l'hôte range les fichiers des VM", "Une base de données SQL", "Un groupe de VM", "Un réseau virtuel"], a: 0,
    e: "Un datastore est un volume vu par l'hôte ESXi pour stocker les VM : disque local, LUN iSCSI ou Fibre Channel formatée en VMFS, ou partage NFS. Pour que vMotion et HA fonctionnent, les hôtes doivent partager les mêmes datastores." },
  { c: 6, q: "Quelle différence entre un vSwitch standard et un vSwitch distribué (vDS) ?",
    o: ["Le standard se configure hôte par hôte ; le distribué est géré une seule fois dans vCenter pour tous les hôtes", "Le distribué est physique", "Le standard est plus rapide", "Aucune"], a: 0,
    e: "Un vSwitch standard existe sur un seul hôte : avec 10 hôtes, il faut refaire 10 fois la même configuration. Le vSwitch distribué est défini dans vCenter et appliqué à tous les hôtes, ce qui garantit une configuration identique. Il demande une licence plus élevée." },
  { c: 6, q: "Dans vSphere, qu'est-ce qu'un groupe de ports (port group) ?",
    o: ["Un ensemble de ports virtuels d'un vSwitch partageant les mêmes réglages (VLAN, sécurité)", "Un groupe de serveurs physiques", "Une règle de pare-feu", "Un câble réseau"], a: 0,
    e: "On branche les cartes réseau des VM sur un port group. Chaque port group porte ses réglages, notamment l'identifiant VLAN : par exemple « VLAN10-Utilisateurs » et « VLAN20-Serveurs » sur le même vSwitch." },
  { c: 6, q: "Quelle différence entre un clone de VM et un modèle (template) ?",
    o: ["Un clone est une VM utilisable tout de suite ; un template est une VM « figée » servant de modèle pour déployer de nouvelles VM", "Aucune", "Le template est plus rapide", "Le clone est une sauvegarde"], a: 0,
    e: "Un clone est une copie complète, démarrable immédiatement. Un template ne peut pas être démarré : il sert de référence pour déployer des VM identiques, souvent avec une personnalisation (nom, IP, sysprep) appliquée au déploiement." },
  { c: 6, q: "Un disque virtuel en « thick provisioning » :",
    o: ["Réserve tout de suite sur le datastore toute la taille annoncée", "Ne prend que la place réellement utilisée", "Est stocké dans le cloud", "Ne peut pas dépasser 10 Go"], a: 0,
    e: "Thick (épais) : un disque de 100 Go occupe immédiatement 100 Go. Les performances sont plus régulières et il n'y a pas de risque de saturation surprise. Thin (fin) : il grossit au fur et à mesure, ce qui économise de la place mais demande de surveiller l'espace libre du datastore." },
  { c: 6, q: "Quel est le format d'export standard d'une VM, importable dans différents hyperviseurs ?",
    o: ["OVF / OVA", "ISO", "ZIP", "VHDX uniquement"], a: 0,
    e: "OVF (Open Virtualization Format) décrit la VM (processeurs, mémoire, réseau) et accompagne ses disques. OVA est le même contenu en un seul fichier. On l'utilise pour échanger des appliances (pare-feu, supervision) entre VMware, VirtualBox…" },
  { c: 6, q: "Quel est l'hyperviseur intégré à Windows Server ?",
    o: ["Hyper-V", "ESXi", "KVM", "VirtualBox"], a: 0,
    e: "Hyper-V est un rôle de Windows Server (et une fonctionnalité de Windows 10/11 Pro). C'est un hyperviseur de type 1 : une fois activé, Windows lui-même tourne au-dessus de l'hyperviseur. Ses disques sont au format VHDX. KVM est l'hyperviseur de Linux, utilisé par Proxmox." },
  { c: 6, q: "Qu'est-ce que Proxmox VE ?",
    o: ["Une plateforme de virtualisation libre basée sur Debian et KVM", "Un antivirus", "Un logiciel de ticketing", "Un protocole réseau"], a: 0,
    e: "Proxmox VE est une solution libre de virtualisation, installée sur Debian. Elle gère des VM (KVM) et des conteneurs (LXC), avec une interface web, la mise en cluster et la haute disponibilité. C'est une alternative fréquente à vSphere dans les PME." },
  { c: 6, q: "Quelle différence principale entre un conteneur (Docker) et une machine virtuelle ?",
    o: ["Le conteneur partage le noyau du système hôte ; la VM embarque son propre système d'exploitation complet", "Le conteneur est plus lourd", "La VM ne peut pas avoir de réseau", "Aucune"], a: 0,
    e: "Une VM virtualise tout le matériel et contient un OS complet : isolation forte, mais lourde. Un conteneur isole seulement l'application et ses dépendances, et utilise le noyau de l'hôte : il démarre en une seconde et consomme peu. Un conteneur Linux ne fait donc pas tourner Windows." },
  { c: 6, q: "Que signifie « surallouer » (overcommit) la mémoire sur un hôte ?",
    o: ["Donner aux VM au total plus de mémoire que l'hôte n'en possède, en comptant sur le fait qu'elles ne l'utilisent pas toutes en même temps", "Ajouter de la RAM physique", "Désactiver la mémoire virtuelle", "Doubler la vitesse de la RAM"], a: 0,
    e: "L'hyperviseur peut promettre 80 Go de RAM aux VM sur un hôte qui en a 64. Cela marche tant que les VM n'utilisent pas tout en même temps. Sinon, l'hôte récupère de la mémoire (ballooning, swap) et les performances chutent : on surveille donc la consommation réelle." },
  { c: 6, q: "Quelle différence entre vSphere HA et vSphere FT (Fault Tolerance) ?",
    o: ["HA redémarre les VM sur un autre hôte après une panne (coupure de quelques minutes) ; FT maintient une copie en direct, sans aucune interruption", "Aucune", "FT est une sauvegarde", "HA ne fonctionne qu'avec une seule VM"], a: 0,
    e: "HA (haute disponibilité) : si un hôte tombe, ses VM redémarrent ailleurs, avec un court arrêt. FT (tolérance de panne) : une VM secondaire tourne en parallèle sur un autre hôte et reprend instantanément. FT est réservée aux VM les plus critiques car elle double les ressources consommées." },
  { c: 6, q: "Qu'est-ce qu'un SAN ?",
    o: ["Un réseau dédié au stockage qui présente aux serveurs des volumes en mode bloc (LUN)", "Un serveur de fichiers partagés en SMB", "Un logiciel antivirus", "Un réseau Wi-Fi"], a: 0,
    e: "Un SAN (Storage Area Network) fournit aux serveurs des disques « bruts » (LUN), en Fibre Channel ou iSCSI : le serveur les formate comme ses propres disques. Un NAS partage des fichiers (SMB, NFS). Les hyperviseurs utilisent souvent un SAN pour les datastores partagés." },
  { c: 6, q: "Qu'est-ce qu'une LUN ?",
    o: ["Un volume logique présenté par une baie de stockage à un ou plusieurs serveurs", "Une carte réseau", "Un type de câble", "Un utilisateur de l'annuaire"], a: 0,
    e: "LUN (Logical Unit Number) : la baie de stockage découpe ses disques en volumes logiques et en présente certains aux serveurs (via iSCSI ou Fibre Channel). Pour l'hôte, une LUN est vue comme un disque local qu'il peut formater (en VMFS pour ESXi)." },
  { c: 6, q: "Une entreprise loue des machines virtuelles chez un hébergeur et installe elle-même le système et les applications. Quel modèle de cloud ?",
    o: ["IaaS", "SaaS", "PaaS", "On-premise"], a: 0,
    e: "IaaS (Infrastructure as a Service) : le fournisseur gère le matériel et la virtualisation, le client gère l'OS, les mises à jour et les applications. PaaS : le fournisseur gère aussi l'OS et le middleware, le client déploie son code. SaaS : le logiciel est prêt à l'emploi (Microsoft 365)." },
  { c: 6, q: "Microsoft 365 (Outlook, Teams en ligne) est un exemple de :",
    o: ["SaaS", "IaaS", "PaaS", "Cloud privé"], a: 0,
    e: "SaaS (Software as a Service) : on utilise directement l'application, le fournisseur gère tout le reste (serveurs, mises à jour, sauvegardes de l'infrastructure). Le client gère seulement ses utilisateurs, ses données et ses paramètres." },
  { c: 6, q: "Qu'est-ce qu'un cloud hybride ?",
    o: ["La combinaison d'une infrastructure sur site (ou cloud privé) et de services de cloud public, reliés entre eux", "Un cloud uniquement public", "Un serveur dans un placard", "Un cloud sans Internet"], a: 0,
    e: "Exemple typique : un Active Directory local synchronisé avec Microsoft Entra ID (Entra Connect), des serveurs sur site et Microsoft 365 dans le cloud. C'est le cadre de la compétence « environnement hybride » du référentiel TSSR." },
  { c: 6, q: "Dans le cloud public, que signifie l'élasticité ?",
    o: ["Pouvoir augmenter ou réduire rapidement les ressources selon le besoin, en payant à l'usage", "Des câbles réseau extensibles", "Une sauvegarde automatique", "Un serveur qui redémarre seul"], a: 0,
    e: "L'élasticité permet d'ajouter des machines ou de la puissance pendant un pic d'activité, puis de les retirer. Avec la facturation à l'usage, on paie ce qu'on consomme. Revers : sans suivi des coûts, la facture peut grimper vite." },
  { c: 6, q: "Chez un fournisseur cloud, pourquoi répartir des VM critiques dans plusieurs « zones de disponibilité » ?",
    o: ["Pour qu'une panne d'un centre de données n'arrête pas tout le service", "Pour payer moins cher", "Pour changer de langue", "Pour accélérer Internet"], a: 0,
    e: "Une zone de disponibilité est un centre de données (ou un groupe) indépendant au sein d'une région, avec sa propre alimentation et son propre réseau. En répartissant les VM sur plusieurs zones, la perte d'une zone n'interrompt pas le service." },
  { c: 6, q: "Qu'est-ce qu'un pool de ressources dans vSphere ?",
    o: ["Un regroupement logique de CPU et de mémoire pour réserver ou limiter les ressources d'un ensemble de VM", "Une piscine de serveurs", "Une liste d'utilisateurs", "Un datastore"], a: 0,
    e: "Un pool de ressources permet par exemple de garantir des ressources à la production et de limiter le laboratoire de test, via des réservations, des limites et des parts (shares). Utile quand plusieurs services partagent les mêmes hôtes." },
  { c: 6, q: "Avant de mettre un hôte ESXi en maintenance (mise à jour), que se passe-t-il pour ses VM ?",
    o: ["Elles doivent être migrées (vMotion, souvent automatique avec DRS) ou arrêtées avant que l'hôte entre en mode maintenance", "Elles sont supprimées", "Rien, elles continuent sur l'hôte", "Elles passent en lecture seule"], a: 0,
    e: "Le mode maintenance n'aboutit que lorsqu'aucune VM ne tourne plus sur l'hôte. Avec DRS, les VM sont déplacées automatiquement par vMotion vers les autres hôtes, sans interruption. On peut ensuite mettre à jour et redémarrer l'hôte." },
  { c: 6, q: "Pourquoi garder un snapshot de VM plusieurs semaines est-il une mauvaise pratique ?",
    o: ["Le fichier delta grossit, ralentit la VM, remplit le datastore et rend la suppression longue et risquée", "Le snapshot s'efface tout seul", "Il bloque les mises à jour Windows", "Il n'y a aucun problème"], a: 0,
    e: "Après un snapshot, toutes les écritures vont dans un fichier delta qui grossit sans arrêt. Les performances baissent, le datastore peut saturer et la consolidation finale devient longue. Un snapshot se garde quelques heures ou jours, le temps d'une intervention, puis se supprime." },
  { c: 6, en: true, q: "Which component lets you manage many ESXi hosts from a single console, with vMotion and HA?",
    o: ["vCenter Server", "VMware Workstation", "VMware Tools", "Windows PE"], a: 0,
    e: "Traduction : « Quel composant permet de gérer de nombreux hôtes ESXi depuis une seule console, avec vMotion et HA ? » vCenter Server centralise la gestion : clusters, migrations à chaud, haute disponibilité, modèles, droits. VMware Tools sont des pilotes installés dans chaque VM." },
  { c: 6, en: true, q: "In cloud computing, which model gives you ready-to-use software through a web browser?",
    o: ["SaaS", "IaaS", "Bare metal", "On-premise"], a: 0,
    e: "Traduction : « En cloud computing, quel modèle fournit un logiciel prêt à l'emploi dans un navigateur ? » C'est le SaaS (Software as a Service), par exemple Microsoft 365 ou une solution de ticketing en ligne. On ne gère ni serveur ni installation." },

  /* ================= Compétence 7 : Accès et sécurité en environnement hybride ================= */
  { c: 7, q: "Sous Windows, que se passe-t-il par défaut pour les droits NTFS d'un nouveau sous-dossier ?",
    o: ["Il hérite des droits de son dossier parent", "Il n'a aucun droit", "Tout le monde a le contrôle total", "Il copie les droits du Bureau"], a: 0,
    e: "Par défaut, les autorisations NTFS se propagent du parent vers les enfants (héritage). On peut désactiver l'héritage sur un dossier pour lui donner des droits spécifiques, en convertissant ou en supprimant les droits hérités." },
  { c: 7, q: "Dans la méthode AGDLP, sur quoi met-on les autorisations d'un dossier partagé ?",
    o: ["Sur un groupe de domaine local", "Directement sur chaque utilisateur", "Sur un groupe global", "Sur l'ordinateur"], a: 0,
    e: "AGDLP : Comptes (Accounts) dans des groupes Globaux (par métier : GG_Compta), groupes globaux dans des groupes de Domaine Local (par ressource et droit : DL_Compta_Lecture), et Permissions données aux groupes de domaine local. On gère ensuite les accès en changeant les appartenances, sans toucher aux droits." },
  { c: 7, q: "Que permet Windows LAPS ?",
    o: ["Gérer un mot de passe administrateur local différent sur chaque poste, changé automatiquement et stocké dans l'annuaire", "Bloquer les clés USB", "Chiffrer le disque", "Créer des utilisateurs du domaine"], a: 0,
    e: "Sans LAPS, le même mot de passe d'administrateur local est souvent partout : un attaquant qui le trouve sur un poste accède à tous. LAPS génère un mot de passe unique par poste, le renouvelle régulièrement et le stocke dans AD ou Entra ID, lisible seulement par les personnes autorisées." },
  { c: 7, q: "Quel réglage de stratégie protège contre les attaques par force brute sur les mots de passe du domaine ?",
    o: ["Le seuil de verrouillage du compte après plusieurs échecs", "L'affichage du dernier utilisateur connecté", "Le fond d'écran", "La mise en veille"], a: 0,
    e: "Après X tentatives échouées, le compte est verrouillé pendant un temps donné : un attaquant ne peut plus essayer des milliers de mots de passe. Attention à ne pas mettre un seuil trop bas, qui verrouillerait les utilisateurs pour une faute de frappe." },
  { c: 7, q: "Qu'apporte le SSO (authentification unique) ?",
    o: ["L'utilisateur s'authentifie une seule fois et accède ensuite à plusieurs applications sans ressaisir son mot de passe", "Un mot de passe différent par application", "Une connexion sans aucune authentification", "Un double écran"], a: 0,
    e: "Avec le SSO, une seule authentification (Kerberos dans le domaine, Entra ID dans le cloud) donne accès à toutes les applications reliées. C'est plus confortable et plus sûr : un seul mot de passe fort, protégé par MFA, plutôt que des dizaines de mots de passe faibles notés sur des post-it." },
  { c: 7, q: "Avec Entra Connect, que fait la « synchronisation du hachage de mot de passe » (PHS) ?",
    o: ["Elle envoie vers Entra ID une empreinte du mot de passe AD, pour que l'utilisateur utilise le même mot de passe dans le cloud", "Elle envoie les mots de passe en clair", "Elle supprime les mots de passe locaux", "Elle désactive le MFA"], a: 0,
    e: "PHS synchronise une empreinte (hachage) du hachage du mot de passe, jamais le mot de passe en clair. L'utilisateur se connecte à Microsoft 365 avec ses identifiants habituels, même si les serveurs locaux sont en panne. L'autre option, l'authentification directe (PTA), fait vérifier le mot de passe par un agent installé sur site." },
  { c: 7, q: "Qu'est-ce qu'une PKI ?",
    o: ["L'infrastructure qui émet et gère les certificats numériques (autorités de certification, révocation)", "Un pare-feu", "Un antivirus", "Un protocole de routage"], a: 0,
    e: "La PKI (infrastructure à clé publique) regroupe les autorités de certification, les règles d'émission et les listes de révocation. Sous Windows Server, c'est le rôle AD CS : il délivre des certificats pour le Wi-Fi 802.1X, les sites intranet en HTTPS ou les cartes à puce." },
  { c: 7, q: "Pourquoi un navigateur affiche-t-il « connexion non sécurisée » sur un site interne en HTTPS ?",
    o: ["Le certificat n'est pas signé par une autorité de confiance du poste, ou il est expiré, ou il ne correspond pas au nom", "Le site est trop lent", "Le poste n'a pas d'antivirus", "Le site est en anglais"], a: 0,
    e: "Le navigateur vérifie trois choses : le certificat est signé par une autorité de confiance, il n'est pas expiré, et le nom du site figure dedans. Pour un intranet, on déploie le certificat de l'autorité interne sur les postes par GPO, et on renouvelle les certificats avant leur expiration." },
  { c: 7, q: "Qu'est-ce qu'un pare-feu « à état » (stateful) ?",
    o: ["Un pare-feu qui suit les connexions et laisse passer automatiquement les réponses aux connexions autorisées", "Un pare-feu matériel uniquement", "Un pare-feu qui bloque tout", "Un pare-feu sans règle"], a: 0,
    e: "Un pare-feu stateful mémorise les connexions établies. Si un poste interne ouvre une connexion web autorisée, la réponse du serveur est acceptée sans règle supplémentaire. Un filtrage sans état exigerait d'écrire une règle pour chaque sens." },
  { c: 7, q: "Quels sont les 3 profils réseau du Pare-feu Windows Defender ?",
    o: ["Domaine, Privé, Public", "Wi-Fi, Ethernet, VPN", "Bas, Moyen, Haut", "Local, Distant, Cloud"], a: 0,
    e: "Windows applique des règles différentes selon le réseau : Domaine (le poste voit un contrôleur du domaine), Privé (réseau de confiance comme à la maison) et Public (café, gare : le plus restrictif). Une règle peut ne s'appliquer qu'à certains profils." },
  { c: 7, q: "Pourquoi un administrateur doit-il avoir deux comptes (un normal et un d'administration) ?",
    o: ["Pour limiter l'exposition des droits élevés : on lit ses mails et navigue avec le compte standard", "Pour avoir deux boîtes mail", "Parce que Windows l'impose", "Pour doubler la sécurité du mot de passe"], a: 0,
    e: "Si l'administrateur ouvre une pièce jointe piégée avec un compte administrateur du domaine, l'attaquant obtient ces droits immédiatement. Avec un compte standard pour la bureautique et un compte d'administration réservé aux tâches d'admin, on applique le moindre privilège. C'est une recommandation forte de l'ANSSI." },
  { c: 7, q: "Quel type de VPN relie de façon permanente deux sites d'une entreprise ?",
    o: ["Un VPN site à site (souvent IPsec)", "Un VPN nomade", "Un partage SMB", "Une connexion RDP"], a: 0,
    e: "Le VPN site à site relie deux réseaux par un tunnel chiffré entre deux routeurs ou pare-feux : les postes de chaque site communiquent comme sur un même réseau. Le VPN nomade (client à site) connecte un télétravailleur au réseau de l'entreprise." },
  { c: 7, q: "Sous Linux, que fait l'outil fail2ban ?",
    o: ["Il bannit temporairement les adresses IP qui accumulent les échecs de connexion (SSH…)", "Il sauvegarde les fichiers", "Il met à jour le système", "Il chiffre le disque"], a: 0,
    e: "fail2ban surveille les journaux. Après plusieurs échecs d'authentification depuis une même IP, il ajoute une règle de pare-feu qui la bloque pendant un temps. Très efficace contre les robots qui testent des mots de passe SSH en boucle." },
  { c: 7, q: "Où place-t-on de préférence un serveur web accessible depuis Internet ?",
    o: ["Dans une DMZ, séparée du réseau interne par un pare-feu", "Sur le réseau des postes utilisateurs", "Sur le contrôleur de domaine", "Chez l'utilisateur"], a: 0,
    e: "La DMZ (zone démilitarisée) est un réseau intermédiaire. Si le serveur web est compromis, l'attaquant reste bloqué par le pare-feu entre la DMZ et le réseau interne, où se trouvent l'AD et les données." },
  { c: 7, q: "Qu'est-ce qu'une attaque par phishing (hameçonnage) ?",
    o: ["Un message frauduleux qui pousse la victime à donner ses identifiants ou à ouvrir un fichier piégé", "Une panne de courant", "Une saturation du réseau", "Une mise à jour ratée"], a: 0,
    e: "Le phishing imite un expéditeur connu (banque, service informatique, Microsoft 365) pour obtenir des identifiants ou faire exécuter un logiciel malveillant. Défenses : sensibilisation des utilisateurs, MFA, filtrage des mails, et un réflexe : signaler au support." },
  { c: 7, q: "Quel est l'intérêt de chiffrer un disque avec BitLocker sur un serveur dans une agence peu sécurisée ?",
    o: ["Si le serveur ou le disque est volé, les données ne sont pas lisibles", "Le serveur démarre plus vite", "Il n'a plus besoin de sauvegarde", "Il ne peut plus être piraté par le réseau"], a: 0,
    e: "BitLocker protège les données « au repos », en cas de vol physique. Il ne protège pas contre une attaque réseau sur un serveur allumé et déverrouillé, et ne remplace pas la sauvegarde." },
  { c: 7, q: "Que fait le protocole 802.1X sur un réseau d'entreprise ?",
    o: ["Il demande une authentification à un appareil avant de lui ouvrir le port du switch ou l'accès Wi-Fi", "Il attribue des VLAN au hasard", "Il chiffre les disques", "Il compresse les fichiers"], a: 0,
    e: "Avec 802.1X, le switch ou la borne Wi-Fi interroge un serveur RADIUS (sous Windows : NPS) avant de laisser passer le trafic. Seuls les appareils et utilisateurs authentifiés (par identifiants ou certificat) accèdent au réseau. Un PC inconnu branché sur une prise reste bloqué." },
  { c: 7, q: "Quelle est la différence entre authentification et autorisation ?",
    o: ["L'authentification vérifie QUI tu es ; l'autorisation détermine CE QUE tu as le droit de faire", "C'est la même chose", "L'autorisation se fait avant l'authentification", "L'authentification ne concerne que le Wi-Fi"], a: 0,
    e: "Authentification : prouver son identité (mot de passe, MFA, certificat). Autorisation : appliquer les droits accordés à cette identité (lecture sur un partage, administration d'un serveur). On s'authentifie d'abord, puis on est autorisé ou non." },
  { c: 7, q: "Dans Microsoft Entra ID, quel principe applique le modèle « Zero Trust » ?",
    o: ["Ne jamais faire confiance par défaut : vérifier explicitement chaque accès (identité, appareil, contexte)", "Faire confiance à tout le réseau interne", "Supprimer les mots de passe", "Ouvrir tous les ports"], a: 0,
    e: "Zero Trust : être sur le réseau de l'entreprise ne suffit plus. Chaque accès est vérifié selon l'identité (MFA), l'état de l'appareil (conforme Intune) et le contexte (pays, risque), avec le moindre privilège. L'accès conditionnel en est l'outil principal." },
  { c: 7, q: "Pourquoi désactiver rapidement le compte d'un salarié qui quitte l'entreprise ?",
    o: ["Pour éviter qu'il, ou un tiers, accède encore aux données et aux applications", "Pour libérer de la place disque", "Pour accélérer le réseau", "Ce n'est pas nécessaire"], a: 0,
    e: "Un compte resté actif est une porte d'entrée : accès aux mails, aux fichiers, au VPN. Une procédure de départ prévoit de désactiver le compte (sans le supprimer tout de suite, pour garder l'historique), de révoquer les accès cloud et de récupérer le matériel." },
  { c: 7, q: "Sous Linux, quelle commande vérifie à quels groupes appartient l'utilisateur paul ?",
    o: ["id paul", "whoami paul", "chmod paul", "ls paul"], a: 0,
    e: "id paul affiche l'UID, le groupe principal et tous les groupes secondaires de paul. Utile pour comprendre pourquoi un utilisateur a accès ou non à un dossier. Attention : un utilisateur ajouté à un groupe doit se reconnecter pour que le changement soit pris en compte." },
  { c: 7, q: "Qu'est-ce qu'un groupe de sécurité « Utilisateurs protégés » (Protected Users) dans Active Directory ?",
    o: ["Un groupe qui applique des protections renforcées aux comptes sensibles (pas de mise en cache des identifiants, Kerberos renforcé)", "Le groupe des invités", "Un groupe sans mot de passe", "Le groupe des imprimantes"], a: 0,
    e: "Les membres de Protected Users bénéficient de protections supplémentaires : pas d'authentification NTLM, pas de mise en cache de leurs identifiants sur les postes, tickets Kerberos à durée réduite. On y place les comptes d'administration pour limiter le vol d'identifiants." },
  { c: 7, en: true, q: "What is the main purpose of a firewall?",
    o: ["To filter network traffic according to rules", "To speed up the Internet connection", "To store backups", "To assign IP addresses"], a: 0,
    e: "Traduction : « Quel est le rôle principal d'un pare-feu ? » Il filtre le trafic réseau selon des règles (adresses, ports, protocoles, sens) : il autorise ce qui est prévu et bloque le reste. Il n'accélère pas la connexion, ne sauvegarde rien et ne distribue pas d'adresses (c'est le rôle du DHCP)." },
  { c: 7, en: true, q: "An attacker sends a fake e-mail from « IT support » asking users to reset their password on a fake website. This attack is called:",
    o: ["Phishing", "DDoS", "Spoofing ARP", "Brute force"], a: 0,
    e: "Traduction : « Un attaquant envoie un faux e-mail du « support informatique » demandant de réinitialiser son mot de passe sur un faux site. Comment s'appelle cette attaque ? » C'est du phishing (hameçonnage). Un DDoS sature un service, la force brute teste des mots de passe en masse, l'usurpation ARP détourne le trafic du réseau local." },

  /* ================= Compétence 8 : Scripts (Bash, PowerShell) optimisés avec l'IA ================= */
  { c: 8, q: "En Bash, que contient $1 dans un script ?",
    o: ["Le premier argument passé au script", "Le nom du script", "Le nombre d'arguments", "Le code de retour"], a: 0,
    e: "Avec ./sauve.sh /home/paul, $1 vaut /home/paul. $0 est le nom du script, $# le nombre d'arguments, $@ la liste de tous les arguments, et $? le code de retour de la dernière commande." },
  { c: 8, q: "En Bash, comment stocker le résultat d'une commande dans une variable ?",
    o: ["date_jour=$(date +%F)", "date_jour = date", "set date_jour date", "date_jour := date"], a: 0,
    e: "$(commande) exécute la commande et remplace l'expression par son résultat (substitution de commande). Attention : pas d'espace autour du = en Bash. date_jour = date serait compris comme une commande « date_jour »." },
  { c: 8, q: "En Bash, quel test compare deux nombres pour savoir s'ils sont égaux ?",
    o: ["[ \"$a\" -eq \"$b\" ]", "[ $a = = $b ]", "if a equals b", "[ $a === $b ]"], a: 0,
    e: "Entre crochets, -eq compare des nombres (-ne différent, -lt inférieur, -gt supérieur). Pour comparer du texte, on utilise = ou !=. Les espaces autour des crochets sont obligatoires." },
  { c: 8, q: "Que fait 2>&1 à la fin d'une commande ?",
    o: ["Il envoie les erreurs (sortie 2) au même endroit que la sortie normale (sortie 1)", "Il lance 2 commandes", "Il supprime les erreurs", "Il double la sortie"], a: 0,
    e: "Une commande a deux sorties : 1 = résultat normal (stdout), 2 = erreurs (stderr). commande > journal.log 2>&1 met les deux dans le même fichier : indispensable pour garder la trace des erreurs d'un script lancé par cron." },
  { c: 8, q: "Comment lire un fichier ligne par ligne en Bash ?",
    o: ["while read -r ligne; do echo \"$ligne\"; done < fichier.txt", "for ligne in fichier.txt", "read fichier.txt", "cat fichier.txt | for"], a: 0,
    e: "La boucle while read lit une ligne à chaque tour, depuis le fichier redirigé avec <. -r évite que les antislashs soient interprétés. C'est la méthode fiable pour traiter une liste d'utilisateurs ou de serveurs." },
  { c: 8, q: "Quelle commande rend un script Bash exécutable ?",
    o: ["chmod +x script.sh", "run script.sh", "exec script.sh", "bash -x script.sh"], a: 0,
    e: "chmod +x ajoute le droit d'exécution, on peut ensuite lancer ./script.sh. bash -x script.sh exécute le script en mode « trace » (chaque commande est affichée avant d'être lancée), très pratique pour déboguer." },
  { c: 8, q: "En Bash, comment définir une fonction ?",
    o: ["sauvegarder() { commandes; }", "function = sauvegarder", "def sauvegarder:", "sub sauvegarder"], a: 0,
    e: "nom() { … } déclare une fonction, appelée ensuite par son nom comme une commande, avec ses arguments en $1, $2. Les fonctions évitent de répéter du code : un script plus court, plus lisible et plus facile à corriger." },
  { c: 8, q: "En PowerShell, quelle cmdlet affiche l'aide d'une commande avec des exemples ?",
    o: ["Get-Help Get-Service -Examples", "Show-Manual Get-Service", "man --ps Get-Service", "Help-Me"], a: 0,
    e: "Get-Help fournit la documentation d'une cmdlet ; -Examples affiche seulement les exemples, -Full tout le détail, et Update-Help télécharge l'aide à jour. C'est le premier réflexe avant de demander à une IA." },
  { c: 8, q: "En PowerShell, à quoi sert Get-Member ?",
    o: ["À afficher les propriétés et méthodes des objets reçus", "À lister les membres d'un groupe AD", "À créer un utilisateur", "À afficher l'aide"], a: 0,
    e: "PowerShell manipule des objets. Get-Service | Get-Member montre tout ce qu'on peut lire (Name, Status, StartType…) et faire (Start, Stop) sur ces objets. Indispensable pour savoir quelles propriétés utiliser ensuite dans Where-Object ou Select-Object." },
  { c: 8, q: "En PowerShell, que représente $_ dans Where-Object { $_.Status -eq 'Running' } ?",
    o: ["L'objet en cours de traitement dans le pipeline", "Le dernier code d'erreur", "Le nom de l'ordinateur", "Une variable vide"], a: 0,
    e: "$_ (ou $PSItem) désigne l'objet qui passe dans le pipeline à ce moment-là. Ici, chaque service est testé : on ne garde que ceux dont le statut est « Running »." },
  { c: 8, q: "Quel opérateur PowerShell signifie « supérieur à » ?",
    o: ["-gt", ">", "-sup", "=>"], a: 0,
    e: "PowerShell utilise des opérateurs en lettres : -eq (égal), -ne (différent), -gt (plus grand), -lt (plus petit), -like (motif avec *). Le signe > sert à la redirection vers un fichier, comme en Bash : erreur fréquente des débutants." },
  { c: 8, q: "Quelle cmdlet exporte une liste d'objets PowerShell dans un fichier lisible par Excel ?",
    o: ["Export-Csv", "Out-Excel", "Save-Table", "Write-Xls"], a: 0,
    e: "Get-ADUser -Filter * | Select-Object Name, Enabled | Export-Csv users.csv -NoTypeInformation -Encoding UTF8 produit un fichier CSV. Inversement, Import-Csv lit un CSV (par exemple une liste de comptes à créer en masse)." },
  { c: 8, q: "Dans un script PowerShell, à quoi sert un bloc param() en début de fichier ?",
    o: ["À déclarer les paramètres que l'on passera au script (avec leur type, et s'ils sont obligatoires)", "À importer un module", "À afficher l'aide", "À définir le mot de passe"], a: 0,
    e: "param([Parameter(Mandatory)][string]$Nom) permet de lancer .\\script.ps1 -Nom Dupont. Le script devient réutilisable sans le modifier, et PowerShell vérifie le type et la présence des valeurs." },
  { c: 8, q: "Quelle différence entre Write-Host et Write-Output en PowerShell ?",
    o: ["Write-Output envoie des données dans le pipeline ; Write-Host écrit seulement à l'écran", "Aucune", "Write-Host est plus rapide", "Write-Output colore le texte"], a: 0,
    e: "Write-Output (souvent implicite) produit des objets que la commande suivante peut traiter ou qu'on peut rediriger dans un fichier. Write-Host affiche du texte à l'écran pour l'utilisateur, sans le transmettre. Pour des données, on utilise Write-Output." },
  { c: 8, q: "Comment lire une variable d'environnement (ex. le nom de l'ordinateur) en PowerShell ?",
    o: ["$env:COMPUTERNAME", "%COMPUTERNAME%", "$COMPUTERNAME", "env(COMPUTERNAME)"], a: 0,
    e: "En PowerShell, les variables d'environnement se lisent avec $env:NOM ($env:USERNAME, $env:TEMP). %NOM% est la syntaxe de l'invite de commandes cmd, $NOM celle de Bash." },
  { c: 8, q: "Quel outil planifie l'exécution d'un script PowerShell sous Windows ?",
    o: ["Le Planificateur de tâches", "cron", "Le Gestionnaire de périphériques", "Paint"], a: 0,
    e: "Le Planificateur de tâches (taskschd.msc, ou la cmdlet Register-ScheduledTask) lance un script à heure fixe, au démarrage ou sur événement. Action typique : powershell.exe -File C:\\Scripts\\sauve.ps1. Sous Linux, l'équivalent est cron." },
  { c: 8, q: "Pourquoi versionner ses scripts avec Git ?",
    o: ["Pour garder l'historique des modifications, revenir en arrière et travailler à plusieurs", "Pour les exécuter plus vite", "Pour les chiffrer", "Pour les rendre payants"], a: 0,
    e: "Git enregistre chaque version avec un message : on voit qui a changé quoi, on peut revenir à une version qui marchait, et plusieurs techniciens peuvent travailler sur les mêmes scripts. Bonne pratique : ne jamais y mettre de mot de passe." },
  { c: 8, q: "Tu demandes à une IA de transformer un script Bash en PowerShell. Que fais-tu du résultat ?",
    o: ["Je le lis, je comprends chaque ligne, je le teste dans un environnement de test avant la production", "Je le lance directement en production", "Je l'envoie aux utilisateurs", "Je le supprime"], a: 0,
    e: "L'IA peut se tromper (cmdlet inexistante, paramètre inventé, logique différente). Le technicien reste responsable : il relit, vérifie dans Get-Help, teste sur une VM ou un compte de test (-WhatIf), puis déploie." },
  { c: 8, q: "Quel est l'intérêt d'ajouter des commentaires dans un script ?",
    o: ["Expliquer le but de chaque partie pour les collègues (et pour soi-même plus tard)", "Accélérer l'exécution", "Chiffrer le code", "Ils sont obligatoires pour que le script marche"], a: 0,
    e: "Un commentaire (# en Bash et en PowerShell) est ignoré à l'exécution. Il explique le pourquoi : ce que fait le bloc, les prérequis, les cas particuliers. Un script non commenté est difficile à maintenir ou à reprendre, et le jury apprécie un code lisible." },
  { c: 8, q: "En Bash, que fait la commande grep -i erreur journal.log ?",
    o: ["Affiche les lignes contenant « erreur » sans tenir compte des majuscules", "Supprime les erreurs", "Compte les lignes", "Remplace « erreur »"], a: 0,
    e: "grep affiche les lignes contenant un motif ; -i ignore la casse (Erreur, ERREUR), -c compte les lignes au lieu de les afficher, -v inverse (lignes ne contenant pas le motif), -r cherche dans tout un dossier." },
  { c: 8, q: "Un script de création de comptes doit éviter de créer un compte déjà existant. Que doit-il faire ?",
    o: ["Vérifier l'existence du compte avant de le créer (test), et journaliser ce qui est fait ou ignoré", "Supprimer tous les comptes d'abord", "Créer en double, ce n'est pas grave", "Demander à l'utilisateur"], a: 0,
    e: "Un bon script est « idempotent » : le relancer ne casse rien. On teste avant d'agir (Get-ADUser dans un try/catch, ou id utilisateur sous Linux), on crée seulement si nécessaire, et on écrit dans un journal ce qui a été fait." },
  { c: 8, q: "En PowerShell, comment récupérer seulement certaines propriétés des objets ?",
    o: ["Select-Object Name, Status", "Where-Object Name", "Get-Only Name", "Filter-Object"], a: 0,
    e: "Select-Object choisit les colonnes (propriétés) à garder. Where-Object filtre les lignes (objets) selon une condition. On les combine souvent : Get-Service | Where-Object Status -eq Running | Select-Object Name." },
  { c: 8, en: true, q: "In PowerShell, which cmdlet lists all available commands containing the word « Service »?",
    o: ["Get-Command *Service*", "Find-Service", "List-Commands Service", "Show-Command -All"], a: 0,
    e: "Traduction : « En PowerShell, quelle cmdlet liste toutes les commandes contenant le mot « Service » ? » Get-Command *Service* (avec des jokers *) retrouve Get-Service, Start-Service, Stop-Service… Avec Get-Help et Get-Member, c'est l'un des 3 outils pour être autonome en PowerShell." },
  { c: 8, en: true, q: "In Bash, which special variable holds the number of arguments passed to a script?",
    o: ["$#", "$?", "$0", "$$"], a: 0,
    e: "Traduction : « En Bash, quelle variable spéciale contient le nombre d'arguments passés à un script ? » C'est $#. $? est le code de retour de la dernière commande, $0 le nom du script, $$ le numéro de processus (PID) du shell." },

  /* ================= Compétence 9 : Continuité et reprise d'activité ================= */
  { c: 9, q: "Quelle différence entre une sauvegarde incrémentale et une différentielle ?",
    o: ["L'incrémentale copie ce qui a changé depuis la DERNIÈRE sauvegarde ; la différentielle, depuis la dernière COMPLÈTE", "Aucune", "La différentielle est toujours plus petite", "L'incrémentale ne sauvegarde que les mails"], a: 0,
    e: "Incrémentale : sauvegardes rapides et petites, mais la restauration demande la complète et TOUTES les incrémentales suivantes. Différentielle : elle grossit de jour en jour, mais la restauration ne demande que la complète et la dernière différentielle." },
  { c: 9, q: "Qu'est-ce que la rotation de sauvegardes GFS ?",
    o: ["Un schéma de conservation Grand-père / Père / Fils (mensuelles, hebdomadaires, quotidiennes)", "Un logiciel de Google", "Un format de fichier", "Une technique RAID"], a: 0,
    e: "GFS : on garde par exemple 7 sauvegardes quotidiennes (fils), 4 hebdomadaires (père) et 12 mensuelles (grand-père). On peut remonter loin dans le temps sans conserver chaque jour, ce qui économise du stockage." },
  { c: 9, q: "Qu'est-ce qu'une sauvegarde « immuable » ?",
    o: ["Une sauvegarde qui ne peut être ni modifiée ni supprimée pendant une durée définie, même par un administrateur", "Une sauvegarde très ancienne", "Une sauvegarde compressée", "Une sauvegarde sur papier"], a: 0,
    e: "L'immuabilité (stockage WORM, dépôt Linux durci, objet verrouillé dans le cloud) empêche un rançongiciel, ou un attaquant qui a volé un compte d'administrateur, de chiffrer ou d'effacer les sauvegardes. C'est devenu une protection essentielle." },
  { c: 9, q: "Que signifie le « 1 » et le « 0 » dans la règle étendue 3-2-1-1-0 ?",
    o: ["1 copie hors ligne ou immuable, et 0 erreur lors des tests de restauration", "1 serveur et 0 utilisateur", "1 jour et 0 heure", "1 disque et 0 RAID"], a: 0,
    e: "3 copies, sur 2 supports différents, dont 1 hors site, plus 1 copie hors ligne (déconnectée) ou immuable, et 0 erreur : les restaurations sont testées et vérifiées. Cette version de la règle 3-2-1 répond à la menace des rançongiciels." },
  { c: 9, q: "Quel niveau de RAID offre de bonnes performances et de la redondance en combinant miroir et agrégat par bandes ?",
    o: ["RAID 10", "RAID 0", "RAID 1", "JBOD"], a: 0,
    e: "Le RAID 10 regroupe des paires de disques en miroir (RAID 1), puis répartit les données sur ces paires (RAID 0). Il supporte la perte d'un disque par paire et offre de très bonnes performances. Il demande au moins 4 disques, et la moitié de la capacité sert au miroir." },
  { c: 9, q: "Combien de disques peut perdre un RAID 5 sans perte de données ?",
    o: ["1", "2", "Aucun", "Tous sauf un"], a: 0,
    e: "Le RAID 5 (3 disques minimum) répartit les données et une parité sur tous les disques : il supporte la perte d'UN disque. Pendant la reconstruction, longue sur les gros disques, une 2e panne est fatale : d'où le RAID 6 (double parité, 2 disques perdus possibles)." },
  { c: 9, q: "Quel RAID n'offre AUCUNE tolérance de panne ?",
    o: ["RAID 0", "RAID 1", "RAID 5", "RAID 6"], a: 0,
    e: "Le RAID 0 répartit les données sur plusieurs disques pour la performance, sans aucune copie : si un disque tombe, tout est perdu. Il ne convient jamais pour des données importantes." },
  { c: 9, q: "Qu'est-ce qu'une BIA (analyse d'impact sur l'activité) ?",
    o: ["L'étude des conséquences d'un arrêt de chaque service pour fixer les priorités, le RTO et le RPO", "Un logiciel antivirus", "Une banque", "Un type de câble"], a: 0,
    e: "La BIA (Business Impact Analysis) mesure, avec les métiers, ce que coûte l'arrêt de chaque service (argent, image, obligations légales). Elle permet de classer les services et de fixer leurs objectifs de reprise : c'est la base du PCA et du PRA." },
  { c: 9, q: "Un site de secours « chaud » (hot site) est :",
    o: ["Un site déjà équipé, avec des systèmes à jour, prêt à reprendre presque immédiatement", "Un local vide", "Un site en plein soleil", "Un site sans électricité"], a: 0,
    e: "Site chaud : matériel en place, données répliquées, reprise en minutes ou en heures (cher). Site tiède : matériel présent mais à configurer et à restaurer. Site froid : un local avec électricité et réseau, il faut tout installer (reprise en jours, mais peu coûteux)." },
  { c: 9, q: "Quelle différence entre réplication et sauvegarde ?",
    o: ["La réplication copie les changements en continu (une suppression est aussi répliquée) ; la sauvegarde conserve des versions passées", "Aucune", "La réplication est plus lente", "La sauvegarde est toujours dans le cloud"], a: 0,
    e: "La réplication maintient une copie à jour, ce qui est idéal pour un RPO faible. Mais si un fichier est supprimé ou chiffré par un rançongiciel, la copie l'est aussi. La sauvegarde garde des points de restauration dans le temps : les deux se complètent." },
  { c: 9, q: "À quoi servent les clichés instantanés (VSS) d'un volume Windows Server ?",
    o: ["À permettre aux utilisateurs de restaurer eux-mêmes une version précédente d'un fichier", "À accélérer le disque", "À compresser les fichiers", "À créer des utilisateurs"], a: 0,
    e: "VSS (Volume Shadow Copy Service) prend des instantanés du volume à heures fixes. Clic droit > « Restaurer les versions précédentes » permet de récupérer un fichier écrasé. C'est pratique, mais ce n'est pas une sauvegarde : les clichés sont sur le même disque." },
  { c: 9, q: "Quelle commande Linux synchronise un dossier vers un autre emplacement en ne copiant que les différences ?",
    o: ["rsync -a /data/ /sauvegarde/data/", "cp -z", "mv -sync", "dd if=/data"], a: 0,
    e: "rsync compare source et destination et ne transfère que ce qui a changé, localement ou vers un autre serveur par SSH. -a (archive) conserve droits, propriétaires, dates et liens. C'est la base de nombreux scripts de sauvegarde Linux." },
  { c: 9, q: "Quel outil intégré permet de sauvegarder un Windows Server, y compris pour une restauration complète ?",
    o: ["Sauvegarde Windows Server (wbadmin)", "Le Bloc-notes", "Le Gestionnaire des tâches", "Paint"], a: 0,
    e: "La fonctionnalité Sauvegarde Windows Server (et sa commande wbadmin) sauvegarde des volumes, l'état du système ou la machine complète pour une restauration « bare metal ». Pour un parc important, on utilise un logiciel dédié (Veeam…)." },
  { c: 9, q: "Pourquoi conserver une copie de sauvegarde hors site ?",
    o: ["Pour survivre à un sinistre touchant le site principal (incendie, inondation, vol)", "Pour accélérer les sauvegardes", "Pour payer moins d'électricité", "Ce n'est pas utile"], a: 0,
    e: "Si les sauvegardes sont dans la même salle que les serveurs, un incendie détruit tout. Une copie dans un autre bâtiment, chez un prestataire ou dans le cloud, permet de reprendre l'activité après un sinistre. C'est le « 1 hors site » de la règle 3-2-1." },
  { c: 9, q: "Après une attaque par rançongiciel, quelle est la première action ?",
    o: ["Isoler les machines touchées du réseau pour stopper la propagation, puis alerter selon la procédure", "Payer la rançon", "Redémarrer tous les serveurs", "Supprimer les sauvegardes"], a: 0,
    e: "On coupe d'abord la propagation (débrancher le réseau, sans forcément éteindre, pour garder des traces), on alerte (responsable, RSSI, ANSSI ou cybermalveillance.gouv.fr), puis on évalue et on restaure depuis des sauvegardes saines. Payer ne garantit rien et finance les attaquants." },
  { c: 9, q: "Pourquoi documenter la procédure de restauration ?",
    o: ["Pour qu'un autre technicien puisse restaurer, même sous stress et sans l'auteur", "Pour faire joli", "Parce que le logiciel l'exige", "Ce n'est pas nécessaire"], a: 0,
    e: "Le jour du sinistre, la personne qui connaît le système peut être absente. Une procédure claire, testée et à jour (où sont les sauvegardes, les mots de passe du coffre, l'ordre de redémarrage) fait gagner des heures et évite les erreurs." },
  { c: 9, q: "Combien de temps d'arrêt par an représente une disponibilité de 99,9 % ?",
    o: ["Environ 8 h 45", "Environ 5 minutes", "Environ 3 jours", "Environ 1 mois"], a: 0,
    e: "Une année compte 8 760 heures. 0,1 % de 8 760 = 8,76 h, soit environ 8 h 45 d'arrêt autorisé par an. 99,99 % ≈ 53 minutes, 99,999 % ≈ 5 minutes. Chaque « 9 » supplémentaire coûte beaucoup plus cher." },
  { c: 9, q: "Qu'est-ce qu'un cluster de basculement (failover cluster) ?",
    o: ["Plusieurs serveurs qui se surveillent : si l'un tombe, un autre reprend ses services automatiquement", "Un groupe de disques RAID", "Une sauvegarde sur bande", "Un réseau Wi-Fi"], a: 0,
    e: "Dans un cluster de basculement (fonctionnalité de Windows Server, ou Pacemaker sous Linux), les nœuds partagent le stockage ou des données répliquées. Si le nœud actif tombe, un autre démarre le service (fichiers, SQL, VM) : la coupure est courte." },
  { c: 9, q: "Quel est le risque si les sauvegardes sont accessibles avec les mêmes comptes que le domaine ?",
    o: ["Un attaquant qui compromet le domaine peut aussi détruire les sauvegardes", "Aucun risque", "Les sauvegardes seront plus lentes", "Les sauvegardes prendront plus de place"], a: 0,
    e: "Les rançongiciels ciblent d'abord les sauvegardes. On isole donc l'infrastructure de sauvegarde : comptes dédiés hors du domaine principal, MFA, réseau séparé, copie immuable ou hors ligne." },
  { c: 9, q: "Pourquoi sauvegarder aussi la configuration des équipements réseau (switchs, routeurs, pare-feux) ?",
    o: ["Pour pouvoir remettre rapidement en service un équipement remplacé ou mal reconfiguré", "Pour accélérer le réseau", "Ce n'est pas utile", "Pour économiser des licences"], a: 0,
    e: "Une configuration de pare-feu ou de switch représente des heures de travail. Si l'équipement tombe ou si une mauvaise modification casse le réseau, la copie de configuration permet de tout restaurer en quelques minutes. On en garde aussi un historique." },
  { c: 9, q: "Que signifie une restauration « granulaire » ?",
    o: ["Restaurer un élément précis (un fichier, un mail, un objet AD) sans restaurer toute la machine", "Restaurer très lentement", "Restaurer sur un autre continent", "Restaurer en mode texte"], a: 0,
    e: "La restauration granulaire permet de récupérer juste ce qui manque : un fichier supprimé, une boîte mail, un utilisateur AD effacé par erreur. Elle est beaucoup plus rapide qu'une restauration complète de la VM ou du serveur." },
  { c: 9, q: "Un onduleur (UPS) signale une coupure de courant. Que doit-il déclencher si elle dure ?",
    o: ["L'arrêt propre des serveurs avant que la batterie soit vide", "Rien", "La suppression des données", "Le redémarrage des postes clients"], a: 0,
    e: "La batterie d'un onduleur ne dure que quelques minutes. Relié aux serveurs (USB, réseau, agent), il déclenche leur arrêt propre avant l'épuisement : on évite la corruption de fichiers et de bases de données. On teste régulièrement les batteries." },
  { c: 9, en: true, q: "What does RTO (Recovery Time Objective) define?",
    o: ["The maximum acceptable time to restore a service after an outage", "The amount of data you can lose", "The number of backups per day", "The cost of a backup"], a: 0,
    e: "Traduction : « Que définit le RTO (objectif de temps de reprise) ? » La durée maximale acceptable pour rétablir un service après une panne. Ne pas confondre avec le RPO (Recovery Point Objective) : la quantité de données qu'on accepte de perdre, donc l'âge maximal de la dernière sauvegarde utilisable." },
  { c: 9, en: true, q: "Why should backups be tested regularly?",
    o: ["To make sure the data can actually be restored when needed", "To make backups faster", "Because backup software expires", "To delete old files"], a: 0,
    e: "Traduction : « Pourquoi faut-il tester régulièrement les sauvegardes ? » Pour être sûr de pouvoir réellement restaurer le jour où on en a besoin. Une sauvegarde jamais testée peut être incomplète, corrompue, ou son mot de passe de chiffrement perdu." },

  /* ================= Compétence 10 : Mises à jour et supervision ================= */
  { c: 10, q: "Quels ports utilise SNMP ?",
    o: ["UDP 161 pour les requêtes, UDP 162 pour les alertes (traps)", "TCP 80 et 443", "TCP 22", "UDP 53"], a: 0,
    e: "Le serveur de supervision interroge les équipements sur le port UDP 161. Les équipements envoient d'eux-mêmes des alertes (traps) vers le port UDP 162 du serveur. Pensez à ouvrir ces ports dans les pare-feux entre les deux." },
  { c: 10, q: "En SNMP v1/v2c, qu'est-ce que la « communauté » ?",
    o: ["Une sorte de mot de passe partagé, transmis en clair, qui autorise la lecture ou l'écriture", "Un groupe d'utilisateurs AD", "Un réseau Wi-Fi", "Un forum d'entraide"], a: 0,
    e: "La communauté (souvent « public » par défaut) est un mot de passe en clair. On change toujours les valeurs par défaut, on limite les adresses autorisées, et on préfère SNMP v3, qui apporte authentification et chiffrement." },
  { c: 10, q: "Dans SNMP, qu'est-ce qu'un OID ?",
    o: ["L'identifiant unique d'une information supervisée (ex. charge CPU, état d'un port)", "Une adresse IP", "Un mot de passe", "Un type de câble"], a: 0,
    e: "Chaque valeur lisible par SNMP a un OID, une suite de nombres (ex. 1.3.6.1.2.1.1.3.0 = durée de fonctionnement). Les OID sont décrits dans des fichiers MIB fournis par les constructeurs, que l'outil de supervision utilise pour afficher des noms lisibles." },
  { c: 10, q: "Supervision avec agent ou sans agent : quelle différence ?",
    o: ["Avec agent, un petit logiciel installé sur la machine remonte des mesures détaillées ; sans agent, on interroge à distance (SNMP, ping, WMI)", "Aucune", "Sans agent, c'est toujours plus précis", "L'agent est un technicien"], a: 0,
    e: "L'agent (Zabbix Agent, NSClient++) donne des métriques fines : services, processus, fichiers de journaux. Sans agent, on utilise ce que la machine expose (SNMP, ping, ports ouverts), souvent la seule option pour un switch ou une imprimante." },
  { c: 10, q: "Quel est le rôle d'un tableau de bord (dashboard) de supervision ?",
    o: ["Donner en un coup d'œil l'état des services et des alertes en cours", "Remplacer les sauvegardes", "Installer les mises à jour", "Créer des utilisateurs"], a: 0,
    e: "Le tableau de bord synthétise : serveurs en vert, orange ou rouge, alertes en cours, graphiques de charge. Il permet de réagir vite et de repérer les tendances (un disque qui se remplit chaque semaine), avant que la panne arrive." },
  { c: 10, q: "Qu'est-ce que le score CVSS associé à une vulnérabilité ?",
    o: ["Une note de gravité de 0 à 10", "Le numéro de série du correctif", "Le nom du découvreur", "La date de publication"], a: 0,
    e: "Le CVSS évalue la gravité d'une faille de 0 à 10 : facilité d'exploitation, besoin d'un accès ou non, impact. 9 à 10 = critique. Il aide à prioriser les correctifs, combiné à l'exposition réelle du système (accessible depuis Internet ou non)." },
  { c: 10, q: "Quel organisme français publie des alertes et avis de sécurité à suivre en veille ?",
    o: ["Le CERT-FR (ANSSI)", "La CNIL uniquement", "L'INSEE", "Météo-France"], a: 0,
    e: "Le CERT-FR, rattaché à l'ANSSI, publie des alertes (failles activement exploitées) et des avis sur les vulnérabilités, avec les correctifs à appliquer. Le suivre fait partie de la veille technologique attendue d'un TSSR." },
  { c: 10, q: "Sur Debian, quel paquet installe automatiquement les mises à jour de sécurité ?",
    o: ["unattended-upgrades", "apt-auto", "update-manager-gui", "yum-cron"], a: 0,
    e: "unattended-upgrades installe automatiquement (et chaque jour) les mises à jour de sécurité. Sur un serveur critique, on peut préférer l'installation manuelle planifiée, pour tester d'abord. yum-cron est l'équivalent sur les anciennes Red Hat / CentOS." },
  { c: 10, q: "Sur Debian, comment savoir si un redémarrage est nécessaire après des mises à jour ?",
    o: ["Le fichier /var/run/reboot-required existe", "L'écran devient rouge", "apt le fait automatiquement", "Il faut toujours redémarrer"], a: 0,
    e: "Quand une mise à jour touche le noyau ou une bibliothèque essentielle, Debian crée /var/run/reboot-required (avec, dans reboot-required.pkgs, la liste des paquets concernés). On planifie alors le redémarrage dans une fenêtre de maintenance." },
  { c: 10, q: "Que fait logrotate sous Linux ?",
    o: ["Il archive, compresse et supprime les anciens journaux pour éviter qu'ils remplissent le disque", "Il fait tourner l'écran", "Il met à jour le noyau", "Il sauvegarde la base de données"], a: 0,
    e: "logrotate fait « tourner » les journaux : chaque jour ou semaine, le fichier courant est renommé (.1, puis .2.gz…), compressé, et les plus anciens sont supprimés. Sans lui, /var/log finirait par remplir le disque." },
  { c: 10, q: "Dans WSUS, que doit faire l'administrateur pour qu'une mise à jour soit installée sur les postes ?",
    o: ["L'approuver pour un groupe d'ordinateurs", "Rien, tout s'installe automatiquement", "L'envoyer par mail", "Redémarrer le serveur WSUS"], a: 0,
    e: "WSUS télécharge les mises à jour de Microsoft, mais les postes ne les installent qu'une fois approuvées par l'administrateur, groupe par groupe. Bonne pratique : approuver d'abord pour un groupe pilote, puis pour toute la production." },
  { c: 10, q: "Pourquoi déployer les mises à jour par « vagues » (anneaux) ?",
    o: ["Pour détecter un problème sur un petit groupe pilote avant de toucher tout le parc", "Pour aller plus vite", "Pour économiser des licences", "Parce que Windows l'impose"], a: 0,
    e: "On installe d'abord sur quelques postes d'informaticiens et d'utilisateurs volontaires, puis sur un service, puis sur tout le monde. Si une mise à jour pose problème, seul le groupe pilote est touché. Intune et Windows Update for Business gèrent ces anneaux." },
  { c: 10, q: "Qu'est-ce qu'une fenêtre de maintenance ?",
    o: ["Une plage horaire convenue avec les utilisateurs où les interventions avec coupure sont autorisées", "Une fenêtre Windows", "Une pièce du serveur", "Un logiciel de ticketing"], a: 0,
    e: "Une fenêtre de maintenance (ex. le mardi de 20 h à 22 h) est annoncée à l'avance aux utilisateurs. On y fait les redémarrages et les mises à jour qui coupent le service, avec un plan de retour arrière. On met aussi la supervision en pause pour éviter les fausses alertes." },
  { c: 10, q: "Dans syslog, quel niveau de gravité est le plus élevé ?",
    o: ["emerg (0)", "info (6)", "debug (7)", "notice (5)"], a: 0,
    e: "Syslog compte 8 niveaux, de 0 (le plus grave) à 7 : emerg, alert, crit, err, warning, notice, info, debug. Un niveau bas (0-3) signale un problème sérieux. On filtre souvent pour n'envoyer au serveur central que warning et au-dessus." },
  { c: 10, q: "Pourquoi centraliser les journaux de tous les serveurs sur un même serveur ?",
    o: ["Pour les conserver même si un serveur est compromis, et pour corréler les événements entre machines", "Pour libérer de la RAM", "Pour accélérer les serveurs", "Ce n'est jamais utile"], a: 0,
    e: "Un attaquant efface souvent les journaux de la machine qu'il a attaquée : une copie centralisée les préserve. On peut aussi suivre un incident sur plusieurs machines à la fois. Outils : serveur rsyslog, Graylog, ELK, ou un SIEM pour la sécurité." },
  { c: 10, q: "Quelle commande Linux montre en temps réel la charge CPU et mémoire des processus ?",
    o: ["top (ou htop)", "ls", "cat /etc/passwd", "ping"], a: 0,
    e: "top affiche en direct les processus les plus gourmands en CPU et en mémoire, la charge moyenne (load average) et l'utilisation du swap. htop en est une version plus lisible, à installer. Sous Windows, l'équivalent est le Gestionnaire des tâches." },
  { c: 10, q: "Un disque d'un serveur est rempli à 85 % et gagne 2 % par semaine. Que fait une bonne supervision ?",
    o: ["Elle alerte au seuil « warning » pour qu'on agisse avant la saturation, grâce à l'analyse de tendance", "Elle attend que le disque soit plein", "Elle supprime des fichiers au hasard", "Elle redémarre le serveur"], a: 0,
    e: "Les seuils (warning à 80 %, critical à 90 %, par exemple) et les graphiques de tendance permettent d'anticiper : à ce rythme, on a environ 7 semaines. On a le temps d'agrandir le volume, de nettoyer ou d'archiver. C'est la supervision proactive." },
  { c: 10, q: "Qu'est-ce qu'un « faux négatif » en supervision ?",
    o: ["Un vrai problème que la supervision n'a pas détecté", "Une alerte qui n'aurait pas dû se déclencher", "Un serveur éteint", "Un mot de passe erroné"], a: 0,
    e: "Faux négatif : tout est vert alors qu'il y a une panne (le ping répond mais le site web est cassé). C'est le plus dangereux. Pour le limiter, on surveille le service réel (page web, port, transaction), pas seulement le ping." },
  { c: 10, q: "Qu'est-ce que la gestion des changements apporte aux mises à jour importantes ?",
    o: ["Une évaluation des risques, une planification, une validation et un plan de retour arrière", "Rien", "Une installation plus rapide", "La suppression des tests"], a: 0,
    e: "Une mise à jour majeure (nouvelle version de l'OS, du logiciel métier) passe par la gestion des changements : analyse d'impact, tests, date validée, information des utilisateurs, plan de retour arrière (snapshot, sauvegarde). On réduit ainsi les mauvaises surprises en production." },
  { c: 10, q: "Pourquoi documenter les versions des systèmes et des logiciels du parc (inventaire) ?",
    o: ["Pour savoir quelles machines sont concernées par une faille et quelles versions arrivent en fin de support", "Pour décorer le bureau", "Pour accélérer les machines", "Ce n'est pas utile"], a: 0,
    e: "Quand une CVE critique sort sur une version donnée, l'inventaire (GLPI, Intune) dit immédiatement quels serveurs ou postes sont exposés. Il sert aussi à anticiper les fins de support : Windows Server, Debian…" },
  { c: 10, q: "Sur Windows, quelle commande PowerShell liste les mises à jour installées ?",
    o: ["Get-HotFix", "Get-Update", "Show-Patch", "List-KB"], a: 0,
    e: "Get-HotFix affiche les correctifs installés (numéro KB, date d'installation). Utile pour vérifier qu'un correctif de sécurité précis est bien présent sur une machine. On peut l'interroger à distance avec -ComputerName." },
  { c: 10, q: "Qu'est-ce qu'un SIEM ?",
    o: ["Un outil qui collecte et corrèle les journaux de sécurité pour détecter les attaques", "Un type de RAID", "Un serveur DHCP", "Un logiciel de bureautique"], a: 0,
    e: "Un SIEM (Security Information and Event Management) centralise les journaux (pare-feux, serveurs, AD, postes) et applique des règles de corrélation : 50 échecs de connexion puis un succès depuis l'étranger déclenchent une alerte. Exemples : Wazuh (libre), Splunk, Microsoft Sentinel." },
  { c: 10, en: true, q: "What does SNMP stand for?",
    o: ["Simple Network Management Protocol", "Secure Network Mail Protocol", "System Node Monitoring Process", "Standard Network Mapping Program"], a: 0,
    e: "Traduction : « Que signifie SNMP ? » Simple Network Management Protocol, protocole simple de gestion de réseau. Il sert à superviser et parfois configurer les équipements réseau, les serveurs et les imprimantes. Version recommandée : SNMPv3, avec authentification et chiffrement." },
  { c: 10, en: true, q: "Your monitoring tool sends 200 alerts a day, most of them unimportant. What is the risk?",
    o: ["Alert fatigue: technicians start ignoring alerts and miss a real incident", "The server will be faster", "Nothing, more alerts is always better", "The licences will expire"], a: 0,
    e: "Traduction : « Ton outil de supervision envoie 200 alertes par jour, la plupart sans importance. Quel est le risque ? » La fatigue d'alerte : à force de bruit, les techniciens ne lisent plus les alertes et ratent la vraie panne. On ajuste les seuils et on regroupe ou supprime les alertes inutiles." },
]);
